import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"29、【坎】 坎下坎上","description":"橫渠易說 - 29、【坎】 坎下坎上","frontmatter":{"title":"29、【坎】 坎下坎上","description":"橫渠易說 - 29、【坎】 坎下坎上"},"headers":[],"relativePath":"classics/hengqu/031.md","filePath":"classics/hengqu/031.md"}'),l={name:"classics/hengqu/031.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_29、【坎】-坎下坎上" tabindex="-1">29、【坎】 坎下坎上 <a class="header-anchor" href="#_29、【坎】-坎下坎上" aria-label="Permalink to “29、【坎】 坎下坎上”">​</a></h1><p>習坎，重襲之義。八純卦惟此加“習”者，餘皆一字可盡其義，坎取其險，故重之而其險乃著也。 色以離見，聲以震聞，臭以巽知，味以坎達。 坎離者，天地之中二氣之正交。然離本陰卦，坎本陽卦，以此見二氣其本如此而交性也，非此二物則無易。</p><h3 id="彖曰-習坎-重險也-水流而不盈-行險而不失其信。-維心亨-乃以剛中也。-行有尚-往有功也。天險-不可升也-地險-山川丘陵也。王公設險以守其國-險之時用大矣哉" tabindex="-1">彖曰：習坎，重險也，水流而不盈，行險而不失其信。“維心亨”，乃以剛中也。“行有尚”，往有功也。天險，不可升也；地險，山川丘陵也。王公設險以守其國，險之時用大矣哉! <a class="header-anchor" href="#彖曰-習坎-重險也-水流而不盈-行險而不失其信。-維心亨-乃以剛中也。-行有尚-往有功也。天險-不可升也-地險-山川丘陵也。王公設險以守其國-險之時用大矣哉" aria-label="Permalink to “彖曰：習坎，重險也，水流而不盈，行險而不失其信。“維心亨”，乃以剛中也。“行有尚”，往有功也。天險，不可升也；地險，山川丘陵也。王公設險以守其國，險之時用大矣哉!”">​</a></h3><h3 id="象曰-水洊至-習坎-君子以常德行-習教事。" tabindex="-1">象曰：水洊至，習坎，君子以常德行，習教事。 <a class="header-anchor" href="#象曰-水洊至-習坎-君子以常德行-習教事。" aria-label="Permalink to “象曰：水洊至，習坎，君子以常德行，習教事。”">​</a></h3><p>可盈則非謂重險也，中柔則心無常，何能亨也!內外皆險，義不可止，故行有尚也。 坎維心亨故行有尚，外雖積險，苟處之心亨不疑，則雖難必濟而往有功也。今水臨萬仞之山，要下即下，無復凝滯(人)［之］在前，惟知有義理而已，則復何迴避，所以心通。</p><h3 id="初六-習坎-入於坎窞-兇。-象曰-習坎入坎-失道兇也。" tabindex="-1">初六，習坎，入於坎窞，兇。 象曰：習坎入坎，失道兇也。 <a class="header-anchor" href="#初六-習坎-入於坎窞-兇。-象曰-習坎入坎-失道兇也。" aria-label="Permalink to “初六，習坎，入於坎窞，兇。 象曰：習坎入坎，失道兇也。”">​</a></h3><p>比於二無出險之志，故云“入於坎窞”也。</p><h3 id="九二-坎有險-求小得。-象曰-求小得-未出中也。" tabindex="-1">九二，坎有險，求小得。 象曰：“求小得”，未出中也。 <a class="header-anchor" href="#九二-坎有險-求小得。-象曰-求小得-未出中也。" aria-label="Permalink to “九二，坎有險，求小得。 象曰：“求小得”，未出中也。”">​</a></h3><p>險難之際，弱必附強，上下俱陰，求必見從，故求則必小得，然二居險中而未出也。</p><h3 id="六三-來之坎坎-險且枕-入於坎窞勿用。-象曰-來之坎坎-終無功也。" tabindex="-1">六三，來之坎坎，險且枕，入於坎窞勿用。 象曰：“來之坎坎”，終無功也。 <a class="header-anchor" href="#六三-來之坎坎-險且枕-入於坎窞勿用。-象曰-來之坎坎-終無功也。" aria-label="Permalink to “六三，來之坎坎，險且枕，入於坎窞勿用。 象曰：“來之坎坎”，終無功也。”">​</a></h3><p>前之入險退(來)［求］，枕險入窞，與初六同。</p><h3 id="六四-樽酒簋貳用缶。納約自牖-終無咎。-象曰-樽酒簋貳-剛柔際也。" tabindex="-1">六四，樽酒簋貳用缶。納約自牖，終無咎。 象曰：“樽酒簋貳”，剛柔際也。 <a class="header-anchor" href="#六四-樽酒簋貳用缶。納約自牖-終無咎。-象曰-樽酒簋貳-剛柔際也。" aria-label="Permalink to “六四，樽酒簋貳用缶。納約自牖，終無咎。 象曰：“樽酒簋貳”，剛柔際也。”">​</a></h3><p>四五俱得陰陽之正，險阻之際，近而相得，誠素既接，雖簡略於禮無咎也。上比於五，有進出之漸，故無兇。</p><h3 id="九五-坎不盈-祗既平-無咎。-象曰-坎不盈-中未大也。" tabindex="-1">九五，坎不盈，祗既平，無咎。 象曰：“坎不盈”，中未大也。 <a class="header-anchor" href="#九五-坎不盈-祗既平-無咎。-象曰-坎不盈-中未大也。" aria-label="Permalink to “九五，坎不盈，祗既平，無咎。 象曰：“坎不盈”，中未大也。”">​</a></h3><p>險難垂出而下比於四，不能勉成其功，光大其志，故聖人惜之曰“祗既平無咎”而已矣，不能往有功也。一本雲：坎盈則進而往有尚矣。</p><h3 id="上六-系用徽纆-置於叢棘-三歲不得-兇。-象曰-上六失道-兇三歲也。" tabindex="-1">上六，系用徽纆，置於叢棘，三歲不得，兇。 象曰：上六失道，兇三歲也。 <a class="header-anchor" href="#上六-系用徽纆-置於叢棘-三歲不得-兇。-象曰-上六失道-兇三歲也。" aria-label="Permalink to “上六，系用徽纆，置於叢棘，三歲不得，兇。 象曰：上六失道，兇三歲也。”">​</a></h3><p>上六過中，逃險而失道者也，不附比陽中，幾於迷復之兇，故為所繫累也。陰柔不能附比於陽，處險之極乘剛，宜其為所拘戮也。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
